/* @lc app=leetcode id=3599 lang=kotlin */ class Solution { fun minXor(nums: IntArray, k: Int): Int = nums.runningFold(0) { a, b -> a xor b }.let { px -> nums.size.let { n -> (1..k).fold(IntArray(n + 1) { if (it == 0) 0 else Int.MAX_VALUE }) { dp, j -> IntArray(n + 1) { i -> if (i < j) Int.MAX_VALUE else (j - 1 until i).minOf { t -> if (dp[t] == Int.MAX_VALUE) Int.MAX_VALUE else maxOf(dp[t], px[i] xor px[t]) } } }[n] } } }